conditionPrometheusQueryLanguage.query:
sum by ("gen_ai.tool.name")(
    increase({
        "__name__"="gen_ai.execute_tool.duration_count", 
        "location"="${LOCATION}",
        "job"="${AGENT_ID}",
        "error.type"!= ""}[5m]
    )
)
/
sum by ("gen_ai.tool.name")(
    increase({
        "__name__"="gen_ai.execute_tool.duration_count", 
        "location"="${LOCATION}",
        "job"="${AGENT_ID}",
    )
) > 0.05
